HTML_B64 = ""
import base64,json,time,threading,webbrowser,urllib.request,urllib.parse
from http.server import ThreadingHTTPServer,BaseHTTPRequestHandler
CACHE={}
LOCK=threading.Lock()
def fetch(url):
    with LOCK:
        hit=CACHE.get(url)
    if hit and time.time()-hit[0]<300:return hit[1]
    req=urllib.request.Request(url,headers={'User-Agent':'Mozilla/5.0','Accept':'application/json'})
    with urllib.request.urlopen(req,timeout=22) as r:data=json.load(r)
    with LOCK:CACHE[url]=(time.time(),data)
    return data
class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        p=urllib.parse.urlparse(self.path);q=urllib.parse.parse_qs(p.query)
        try:
            if p.path=='/':
                body=base64.b64decode(HTML_B64);ctype='text/html; charset=utf-8'
            else:
                cc=q.get('cc',['CN'])[0].upper()
                if len(cc)!=2 or not cc.isalpha():raise ValueError('Invalid region')
                app=q.get('id',[''])[0]
                if p.path=='/api/search':
                    term=q.get('q',[''])[0][:100]
                    data=fetch('https://store.steampowered.com/api/storesearch/?'+urllib.parse.urlencode({'term':term,'cc':cc,'l':'schinese'}))
                elif p.path=='/api/price' and app.isdigit():
                    data=fetch('https://store.steampowered.com/api/appdetails?'+urllib.parse.urlencode({'appids':app,'cc':cc,'l':'schinese'}))
                elif p.path=='/api/regions' and app.isdigit():data=fetch('https://steamraw.com/api/app/'+app+'/regions')
                else:self.send_error(404);return
                body=json.dumps(data,ensure_ascii=False).encode();ctype='application/json; charset=utf-8'
            self.send_response(200);self.send_header('Content-Type',ctype);self.send_header('Cache-Control','no-store');self.end_headers();self.wfile.write(body)
        except Exception:
            self.send_response(502);self.send_header('Content-Type','application/json');self.end_headers();self.wfile.write(b'{"error":"Source unavailable. Please retry."}')
    def log_message(self,*args):pass
if __name__=='__main__':
    server=ThreadingHTTPServer(('127.0.0.1',0),Handler)
    url='http://127.0.0.1:'+str(server.server_port)
    print('Steam dashboard: '+url+'  (Ctrl+C to stop)')
    threading.Timer(.5,lambda:webbrowser.open(url)).start()
    try:server.serve_forever()
    except KeyboardInterrupt:server.server_close()
